import urllib.request

# Try the direct URL with space replaced by underscore (common Wikipedia convention)
url = "https://en.wikipedia.org/wiki/Wikipedia:Featured_article_candidates/November_2016"

headers = {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
}

req = urllib.request.Request(url, headers=headers)

try:
    response = urllib.request.urlopen(req)
    html_content = response.read().decode('utf-8')
    print(f"Successfully fetched page directly!")
    print(f"Content length: {len(html_content)} characters")

    # Look for the page title
    title_pattern = r'<title>(.*?)</title>'
    title_match = re.search(title_pattern, html_content)
    if title_match:
        print(f"Page title: {title_match.group(1)}")

    # Look for "Featured article candidates" in the content
    if "Featured article candidates" in html_content:
        print("Found 'Featured article candidates' in content")

    # Look for "November 2016" in the content  
    if "November 2016" in html_content:
        print("Found 'November 2016' in content")

    # Look for dinosaur-related content
    dinosaur_keywords = ['dinosaur', 'Dinosaur', 'saur', 'Saur', 'tyrannosaur', 'Tyrannosaur', 
                        'triassic', 'Triassic', 'cretaceous', 'Cretaceous', 'jurassic', 'Jurassic']

    for keyword in dinosaur_keywords:
        if keyword in html_content:
            print(f"Found keyword '{keyword}' in content")

except Exception as e:
    print(f"Error fetching page: {e}")

# Also try the Wikipedia API to search for the page
print("\n\nTrying Wikipedia API search...")
search_api_url = "https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch=Featured+article+candidates+November+2016&format=json"
search_req = urllib.request.Request(search_api_url, headers=headers)

try:
    search_response = urllib.request.urlopen(search_req)
    search_data = search_response.read().decode('utf-8')
    search_parsed = json.loads(search_data)

    if 'query' in search_parsed and 'search' in search_parsed['query']:
        search_results = search_parsed['query']['search']
        print(f"\nFound {len(search_results)} search results:")
        for result in search_results:
            print(f"  - {result['title']} (snippet: {result['snippet'][:100]}...)")
    else:
        print("No search results found")

except Exception as e:
    print(f"Error with search API: {e}")", "session_id": 1774003388}

