import urllib.request
import urllib.error
import re
from html.parser import HTMLParser

class LinkParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.links = []
        self.current_tag = None
        self.current_href = None

    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            href = None
            for attr, value in attrs:
                if attr == 'href':
                    href = value
                    break
            if href:
                self.current_href = href
                self.current_tag = 'a'

    def handle_data(self, data):
        if self.current_tag == 'a' and self.current_href:
            self.links.append((self.current_href, data.strip()))

    def handle_endtag(self, tag):
        if tag == 'a':
            self.current_tag = None
            self.current_href = None

url = "https://en.wikipedia.org/wiki/Wikipedia:Featured_article_candidates/November_2016"
print(f"Fetching URL: {url}")

try:
    req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
    response = urllib.request.urlopen(req)
    html_content = response.read().decode('utf-8')

    # Check for 404 indicators
    if "404" in html_content or "does not exist" in html_content.lower():
        print("Page is a 404 error page")
        print("We'll need to search Wikipedia instead")
    else:
        print(f"Page fetched successfully (size: {len(html_content)} bytes)")

        # Extract title
        title_match = re.search(r'<title>(.*?)</title>', html_content, re.IGNORECASE)
        if title_match:
            print(f"Page title: {title_match.group(1)}")

except urllib.error.HTTPError as e:
    print(f"HTTP Error: {e.code} - {e.reason}")
    if e.code == 404:
        print("Page not found (404)")
except Exception as e:
    print(f"Error fetching page: {e}")"}

